    """Total the amount column per category.

    Returns {category: total} with each total rounded to 2 decimals.
    Category keys are lowercase with surrounding whitespace stripped.
    Amounts may be quoted and may use $ and thousands separators.
    An amount wrapped in parentheses is negative, accounting style.
    Rows with a missing or empty amount are skipped, as are blank lines.
    """
    import csv
    import io

    def parse_amount(raw):
        value = raw.strip()
        if not value:
            return None
        negative = False
        if value.startswith("(") and value.endswith(")"):
            negative = True
            value = value[1:-1].strip()
        if value.startswith("-"):
            negative = not negative
            value = value[1:].strip()
        value = value.lstrip("$").replace(",", "").replace(")", "").replace("(", "")
        value = value.strip()
        if not value:
            return None
        return float(value) * (-1 if negative else 1)

    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return totals
    for parts in rows[1:]:
        if not parts or all(not cell.strip() for cell in parts):
            continue
        while len(parts) < 3:
            parts.append("")
        category = parts[1].strip().lower()
        amount = parse_amount(parts[2])
        if amount is None or not category:
            continue
        totals[category] = totals.get(category, 0) + amount
    return {category: round(total, 2) for category, total in totals.items()}
